import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';

export const fetchTodos = createAsyncThunk(
  'todos/fetch',
  async (_, { rejectWithValue }) => {
    try {
      const response = await fetch('/api/todos');
      if (!response.ok) {
        return rejectWithValue({ code: response.status, message: response.statusText });
      }
      return response.json();
    } catch (err) {
      return rejectWithValue({ code: 'NETWORK', message: err.message });
    }
  }
);

const todosSlice = createSlice({
  name: 'todos',
  initialState: { items: [], status: 'idle', error: null },
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(fetchTodos.pending, (state) => {
        state.status = 'loading';
        state.error = null;
      })
      .addCase(fetchTodos.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.items = action.payload;
      })
      .addCase(fetchTodos.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.payload ?? { message: 'Unknown error' };
      });
  },
});

const errorLogger = (store) => (next) => (action) => {
  if (action.type.endsWith('/rejected')) {
    const error = action.payload ?? action.error?.message ?? 'Unknown error';

    console.error('[Redux] ', action.type, error);

    if (typeof window !== 'undefined' && window.Sentry) {
      window.Sentry.captureException(error);
    }

    store.dispatch(showToast({ kind: 'error', message: String(error) }));
  }
  return next(action);
};

const store = configureStore({
  reducer: rootReducer,
  middleware: (getDefault) => getDefault().concat(errorLogger),
});

async function withRetry(fn, maxAttempts = 3) {
  let attempt = 0;
  while (attempt < maxAttempts) {
    try {
      return await fn();
    } catch (err) {
      attempt += 1;
      if (attempt === maxAttempts) throw err;
      await new Promise((r) => setTimeout(r, 2 ** attempt * 250));
    }
  }
}

export const fetchTodos = createAsyncThunk('todos/fetch', async () => {
  const response = await withRetry(() => fetch('/api/todos'));
  return response.json();
});
